    enum_comp['theta_y'] = theta_y
    return ModImputeMultiResult(
        method="EM",
        mle_call="multinomial_em",
        mle_iter=iter_count,
        mle_log_lik=log_lik,
        mle_cp=conj_prior,
        mle_x_y=enum_comp.drop(columns=['alpha'], errors='IGNORE')
    )

